<template><div class="toast-stack" aria-live="polite"><template v-for="(item, index) in toast.messages" :key="item?.id ?? index"><div v-if="item" class="toast" :class="`toast-${item.type}`"><Icon :name="item.type === 'success' ? 'heroicons:check-circle' : item.type === 'error' ? 'heroicons:x-circle' : 'heroicons:information-circle'" /><span>{{ item.message }}</span></div></template></div></template><script setup lang="ts">const toast = useToast()</script>
